static const std::string Source=R"({"version":1,"nodes":[{"id":"spawn","type":"Spawn","values":{"rate":60,"burst":2,"duration":1,"loop":false},"inputs":{}},{"id":"init","type":"Initialize","values":{"lifetimeMin":2,"lifetimeMax":2,"speedMin":0,"speedMax":0,"sizeMin":1,"sizeMax":1},"inputs":{"in":"spawn"}},{"id":"gravity","type":"Gravity","values":{"acceleration":[0,0,0]},"inputs":{"in":"init"}},{"id":"out","type":"Output","values":{},"inputs":{"in":"gravity"}}]})";
static void Simulation(){
 auto graph=VFXGraph::FromSource(Source);assert(graph.IsValid());assert(!VFXGraph::FromSource("{}").IsValid());assert(!VFXGraph::FromSource(R"({"version":2,"nodes":[]})").IsValid());
 auto cyclic=Source;auto at=cyclic.find("\"inputs\":{}");cyclic.replace(at,11,"\"inputs\":{\"in\":\"out\"}");assert(!VFXGraph::FromSource(cyclic).IsValid());
 Scene scene;scene.AddSystem<ParticleSystem>();auto a=scene.CreateEntity(),b=scene.CreateEntity();a.AddComponent<ParticleEmitter>();b.AddComponent<ParticleEmitter>();VFX::SetGraph(a,graph);VFX::SetGraph(b,graph);VFX::Simulate(a,.5f);for(int i=0;i<60;++i)VFX::Simulate(b,1.f/120);auto x=VFX::GetParticles(a),y=VFX::GetParticles(b);assert(!x.empty()&&x.size()==y.size());for(std::size_t i=0;i<x.size();++i){assert(x[i].Id==y[i].Id);assert((x[i].Position-y[i].Position).Length()<1e-5f);assert(std::abs(x[i].Age-y[i].Age)<1e-5f);}
 VFX::Pause(a);double time=VFX::GetStatistics(a).Time;VFX::Simulate(a,.1f);assert(VFX::GetStatistics(a).Time==time);VFX::Resume(a);VFX::Simulate(a,.1f);assert(VFX::GetStatistics(a).Time>time);
 VFX::Restart(a);VFX::Emit(a,3);assert(VFX::GetStatistics(a).Alive==3);auto first=VFX::GetParticles(a);VFX::Restart(a);VFX::Emit(a,3);assert(VFX::GetParticles(a)[0].Rotation==first[0].Rotation);a.GetComponent<ParticleEmitter>().MaxParticles=4;VFX::Emit(a,10);assert(VFX::GetStatistics(a).Alive==4&&VFX::GetStatistics(a).Dropped==9);assert(!VFX::GetEvents(a).empty());VFX::SetGraph(a,graph);assert(VFX::GetEvents(a).empty()&&VFX::GetStatistics(a).Capacity==4);
 VFX::Stop(a);assert(!VFX::GetStatistics(a).Playing&&VFX::GetParticles(a).empty());VFX::Simulate(b,3);assert(VFX::GetParticles(b).empty()&&!VFX::GetStatistics(b).Playing);
 auto c=scene.CreateEntity();auto& emitter=c.AddComponent<ParticleEmitter>();emitter.Space=ParticleSimulationSpace::World;c.GetComponent<Transform>().Position={10,0,0};VFX::SetGraph(c,graph);VFX::Emit(c,1);assert(std::abs(VFX::GetParticles(c)[0].Position.X-10)<1e-6f);c.GetComponent<Transform>().Position.X=20;assert(VFX::GetParticles(c)[0].Position.X==10);
 emitter.Enabled=false;auto before=VFX::GetStatistics(c).Time;VFXAccess::Update(scene,.1f);assert(VFX::GetStatistics(c).Time==before);
 scene.DestroyEntity(c);VFXAccess::Update(scene,.1f);
}
static std::string Block(std::string source,const std::string& type,const std::string& values,const std::string& id){
 auto output=source.find("\"id\":\"out\"");auto input=source.find("\"in\":\"",output)+6;auto end=source.find('"',input);auto previous=source.substr(input,end-input);source.replace(input,end-input,id);source.insert(source.size()-2,",{\"id\":\""+id+"\",\"type\":\""+type+"\",\"values\":"+values+",\"inputs\":{\"in\":\""+previous+"\"}}");return source;
}
static void AdvancedModules(){
 Scene scene;scene.AddSystem<ParticleSystem>();auto entity=scene.CreateEntity();auto& c=entity.AddComponent<ParticleEmitter>();c.Space=ParticleSimulationSpace::World;c.Backend=ParticleSimulationBackend::GPUAnalytic;VFXAccess::SetGPUAvailable(scene,true);
 auto trails=Block(Source,"Trails",R"({"lifetime":0.25,"minDistance":0.001,"width":0.1,"segments":8})","trails");trails=Block(trails,"Velocity",R"({"velocity":[1,0,0]})","velocity");auto graph=VFXGraph::FromSource(trails);assert(graph.IsValid());VFX::SetGraph(entity,graph);VFX::Emit(entity,1);VFX::Simulate(entity,.1f);assert(VFX::GetStatistics(entity).TrailPoints>1&&VFX::GetStatistics(entity).Backend==ParticleSimulationBackend::CPU);assert(!VFX::GetStatistics(entity).BackendMessage.empty());VFX::Stop(entity,false);VFX::Simulate(entity,2.1f);assert(VFX::GetStatistics(entity).Alive==0&&VFX::GetStatistics(entity).TrailPoints>0);VFX::Simulate(entity,.5f);assert(VFX::GetStatistics(entity).TrailPoints==0);
 c.Backend=ParticleSimulationBackend::CPU;entity.GetComponent<Transform>().Position={0,1,0};auto collision=Block(Source,"Velocity",R"({"velocity":[0,-4,0]})","velocity");collision=Block(collision,"Collision",R"({"mode":1,"radius":0.1,"bounce":0.5})","collision");VFX::SetGraph(entity,VFXGraph::FromSource(collision));VFX::Stop(entity);VFX::Emit(entity,1);VFX::Simulate(entity,.4f);auto particles=VFX::GetParticles(entity);assert(particles.size()==1&&particles[0].Position.Y>=.099f&&particles[0].Velocity.Y>0);auto events=VFX::GetEvents(entity);assert(std::any_of(events.begin(),events.end(),[](const ParticleEvent& e){return e.Type==ParticleEventType::Collision&&e.Normal.Y>.99f;}));
 auto floor=scene.CreateEntity("Floor");floor.GetComponent<Transform>().Position.Y=-.5f;floor.AddComponent<ShapeCollider>().Size={10,1,10};PhysicsModule().Start(scene);auto world=collision;auto mode=world.find("\"mode\":1");world.replace(mode,8,"\"mode\":0");VFX::SetGraph(entity,VFXGraph::FromSource(world));VFX::Stop(entity);VFX::Emit(entity,1);VFX::Simulate(entity,.4f);particles=VFX::GetParticles(entity);assert(particles[0].Position.Y>=.09f&&particles[0].Velocity.Y>0);assert(VFX::GetStatistics(entity).CollisionQueries>0);events=VFX::GetEvents(entity);assert(std::any_of(events.begin(),events.end(),[&](const ParticleEvent& e){return e.Type==ParticleEventType::Collision&&e.Collider==floor.GetUUID();}));
 auto body=scene.CreateEntity("Impulse target");body.GetComponent<Transform>().Position.Y=.5f;body.AddComponent<ShapeCollider>();body.AddComponent<Rigidbody>().GravityFactor=0;PhysicsModule().Synchronize(scene);entity.GetComponent<Transform>().Position.Y=2;world=Block(world,"Physics",R"({"sceneGravity":false,"mass":1,"transferImpulse":true})","physics");VFX::SetGraph(entity,VFXGraph::FromSource(world));VFX::Stop(entity);VFX::Emit(entity,1);VFX::Simulate(entity,.4f);assert(scene.GetPhysics().GetLinearVelocity(body).Y<-.1f);PhysicsModule().Release(scene);
 auto lighting=Block(Source,"Lights",R"({"intensity":300,"range":2,"maxLights":2})","lights");VFX::SetGraph(entity,VFXGraph::FromSource(lighting));VFX::Stop(entity);VFX::Emit(entity,5);const auto entities=scene.GetEntityCount();auto lights=VFXAccess::GetLights(scene);assert(lights.size()==2&&lights[0].Intensity==300&&lights[0].Range==2);assert(scene.GetEntityCount()==entities&&VFX::GetStatistics(entity).EmittedLights==2);c.Enabled=false;assert(VFXAccess::GetLights(scene).empty());c.Enabled=true;
 c.Backend=ParticleSimulationBackend::GPUAnalytic;VFX::SetGraph(entity,VFXGraph::FromSource(Source));VFX::Stop(entity);VFX::Emit(entity,1);VFX::Simulate(entity,.2f);assert(VFX::GetStatistics(entity).Backend==ParticleSimulationBackend::GPUAnalytic);auto snapshot=VFX::GetParticles(entity);assert(snapshot.size()==1&&snapshot[0].Position.Y==2);VFXAccess::SetGPUAvailable(scene,false);assert(VFX::GetStatistics(entity).Backend==ParticleSimulationBackend::CPU&&!VFX::GetStatistics(entity).BackendMessage.empty());
 auto bad=Block(Source,"Trails",R"({"segments":1})","bad");assert(!VFXGraph::FromSource(bad).IsValid());
}
static void Write(const std::filesystem::path& p,const std::string& text){std::ofstream f(p,std::ios::binary);f<<text;assert(f.good());}
static void Imports(){auto root=std::filesystem::temp_directory_path()/("bazzalt-vfx-"+UUID::Generate().ToString());std::filesystem::create_directories(root/"Assets");auto child=UUID::Generate();auto parent=UUID::Generate();auto import=[&](UUID id){return "{\"version\":1,\"nodes\":[{\"id\":\"import\",\"type\":\"Import\",\"values\":{\"asset\":\""+id.ToString()+"\"},\"inputs\":{}},{\"id\":\"output\",\"type\":\"Output\",\"values\":{},\"inputs\":{\"in\":\"import\"}}]}";};
 Write(root/"Assets/child.vfx",Source);Write(root/"Assets/parent.vfx",import(child));for(auto item:{std::pair{"child.vfx",child},std::pair{"parent.vfx",parent}})Write(root/"Assets"/(std::string(item.first)+".meta"),"FormatVersion: 1\nUUID: \""+item.second.ToString()+"\"\nImporter: Bazzalt.VFX\nImporterVersion: 0\nSourceHash: \"\"\nCachePath: \"\"\nSettings: {}\n");Write(root/"Game.bproject","FormatVersion: 1\nProjectUUID: \""+UUID::Generate().ToString()+"\"\nName: VFX\nAssetDirectory: Assets\nStartupScene: \"\"\n");
 Write(root/"Assets/particle.gltf",R"({"asset":{"version":"2.0"},"buffers":[{"uri":"geometry.bin","byteLength":36}],"bufferViews":[{"buffer":0,"byteLength":36}],"accessors":[{"bufferView":0,"componentType":5126,"count":3,"type":"VEC3","min":[0,0,0],"max":[1,1,0]}],"meshes":[{"primitives":[{"attributes":{"POSITION":0}}]}],"nodes":[{"mesh":0,"translation":[2,0,0]}],"scenes":[{"nodes":[0]}],"scene":0})");{const std::array<float,9> points{0,0,0,1,0,0,0,1,0};std::ofstream buffer(root/"Assets/geometry.bin",std::ios::binary);buffer.write(reinterpret_cast<const char*>(points.data()),sizeof(points));}
 {Engine host;assert(host.LoadProject(root/"Game.bproject",false));auto model=AssetManager::GetAsset(root/"Assets/particle.gltf");assert(model);VFXProgram meshProgram;meshProgram.Mesh=model->Id;auto meshVertices=ParticleMesh(meshProgram);assert(meshVertices.size()==3&&std::abs(meshVertices[0].Position.X-2)<.001f);meshProgram.MeshNode=99;bool missing=false;try{ParticleMesh(meshProgram);}catch(const std::invalid_argument&){missing=true;}assert(missing);auto graph=VFXGraph::Load(parent);assert(graph.IsValid());assert(graph.GetDependencies()==std::vector<UUID>{child});assert(AssetManager::GetDependencies(parent)==std::vector<UUID>{child});auto entity=host.GetScene().CreateEntity();entity.AddComponent<ParticleEmitter>().Graph=parent;auto scenePath=root/"Assets/Main.bscene";assert(host.SaveScene(scenePath));auto* descriptor=host.GetSceneSerializer().GetComponents().Find("Bazzalt.ParticleEmitter");assert(descriptor);PropertyMap fields;assert(descriptor->Serialize(entity,fields));fields.erase("Backend");entity.GetComponent<ParticleEmitter>().Backend=ParticleSimulationBackend::GPUAnalytic;assert(descriptor->Deserialize(entity,fields,1));assert(entity.GetComponent<ParticleEmitter>().Backend==ParticleSimulationBackend::CPU);auto loaded=host.LoadSceneAsset(scenePath);assert(loaded&&loaded->GetEntity(entity.GetUUID()).GetComponent<ParticleEmitter>().Graph==parent);Write(root/"Assets/child.vfx",import(parent));assert(host.RefreshAssets());assert(!VFXGraph::Load(parent).IsValid());}
 std::filesystem::remove_all(root);
}
static void GPU(){
 RenderBackend backend;assert(backend.ConfigureBackend("vulkan"));assert(backend.Initialize(false));Scene scene;scene.AddSystem<ParticleSystem>();scene.AddSystem<CameraSystem>(backend);scene.AddSystem<PrimitiveSystem>(backend);backend.SetGuiScene(&scene);
 auto e=scene.CreateEntity();auto& emitter=e.AddComponent<ParticleEmitter>();VFX::SetGraph(e,VFXGraph::FromSource(Source));VFX::Stop(e);VFX::Emit(e,1);auto camera=scene.CreateEntity();camera.GetComponent<Transform>().Position={0,0,5};auto& c=camera.AddComponent<Camera>();c.PostProcessing.Enabled=false;TextureDescriptor descriptor;descriptor.Width=descriptor.Height=64;descriptor.Mipmaps=false;auto texture=Texture::Create(descriptor);c.SetRenderTarget(texture);scene.GetSystem<CameraSystem>().Synchronize(scene);auto& engine=backend.GetEngine();
 const auto read=[&]{for(int i=0;i<3;++i){backend.Render();engine.flushAndWait();engine.pumpMessageQueues();}auto* target=backend.GetCameraOutputTarget(camera.GetUUID());assert(target);std::vector<unsigned char> pixels(64*64*4);bool done=false;backend.GetRenderer().readPixels(target,0,0,64,64,{pixels.data(),pixels.size(),filament::Texture::Format::RGBA,filament::Texture::Type::UBYTE,[](void*,std::size_t,void* p){*static_cast<bool*>(p)=true;},&done});engine.flushAndWait();engine.pumpMessageQueues();assert(done);return pixels;};
 auto pixels=read();auto center=(32*64+32)*4;assert(pixels[center]>50);
 emitter.Backend=ParticleSimulationBackend::GPUAnalytic;auto moving=Block(Source,"Velocity",R"({"velocity":[2,0,0]})","velocity");auto at=moving.find("\"sizeMin\":1");moving.replace(at,11,"\"sizeMin\":0.25");at=moving.find("\"sizeMax\":1");moving.replace(at,11,"\"sizeMax\":0.25");VFX::SetGraph(e,VFXGraph::FromSource(moving));VFX::Stop(e);VFX::Emit(e,1);VFX::Simulate(e,.5f);assert(VFX::GetStatistics(e).Backend==ParticleSimulationBackend::GPUAnalytic);assert(std::abs(VFX::GetParticles(e)[0].Position.X-1)<.001f);pixels=read();unsigned count=0;float xsum=0;for(unsigned y=0;y<64;++y)for(unsigned x=0;x<64;++x)if(pixels[(y*64+x)*4]>20){++count;xsum+=x;}assert(count&&xsum/count>36&&pixels[center]<5);
 emitter.Enabled=false;pixels=read();assert(pixels[center]<5);emitter.Enabled=true;
 auto mesh=Block(Source,"MeshOutput",R"({"primitive":0,"lit":false})","mesh");VFX::SetGraph(e,VFXGraph::FromSource(mesh));VFX::Stop(e);VFX::Emit(e,1);pixels=read();assert(pixels[center]>50&&VFX::GetStatistics(e).Backend==ParticleSimulationBackend::GPUAnalytic);
 VFX::Stop(e);auto target=scene.CreateEntity("Lit target");target.AddComponent<PrimitiveObject>();scene.GetSystem<PrimitiveSystem>().Synchronize(scene);pixels=read();const auto dark=pixels[center];
 auto lamp=scene.CreateEntity("Particle light");lamp.GetComponent<Transform>().Position={0,0,2};lamp.AddComponent<ParticleEmitter>();auto light=Block(Source,"Lights",R"({"intensity":1000000,"range":8,"maxLights":1})","light");at=light.find("\"sizeMin\":1");light.replace(at,11,"\"sizeMin\":0");at=light.find("\"sizeMax\":1");light.replace(at,11,"\"sizeMax\":0");VFX::SetGraph(lamp,VFXGraph::FromSource(light));VFX::Stop(lamp);VFX::Emit(lamp,1);const auto entities=scene.GetEntityCount();pixels=read();assert(pixels[center]>dark+10&&VFX::GetStatistics(lamp).EmittedLights==1&&scene.GetEntityCount()==entities);VFX::Clear(lamp);pixels=read();assert(pixels[center]<=dark+2);
 target.GetComponent<PrimitiveObject>().Visible=false;scene.GetSystem<PrimitiveSystem>().Synchronize(scene);emitter.Backend=ParticleSimulationBackend::CPU;auto trail=Block(Source,"Velocity",R"({"velocity":[5,0,0]})","velocity");trail=Block(trail,"Trails",R"({"width":0.3,"lifetime":1,"minDistance":0.001})","trail");at=trail.find("\"lifetimeMin\":2");trail.replace(at,15,"\"lifetimeMin\":0.1");at=trail.find("\"lifetimeMax\":2");trail.replace(at,15,"\"lifetimeMax\":0.1");VFX::SetGraph(e,VFXGraph::FromSource(trail));VFX::Stop(e);VFX::Emit(e,1);VFX::Simulate(e,.2f);assert(VFX::GetStatistics(e).Alive==0&&VFX::GetStatistics(e).TrailPoints>1);pixels=read();bool ribbonVisible=false;for(std::size_t i=0;i<pixels.size();i+=4)ribbonVisible|=pixels[i]>10||pixels[i+1]>10||pixels[i+2]>10;assert(ribbonVisible);
 VFX::Stop(e);scene.RemoveSystem<PrimitiveSystem>();scene.RemoveSystem<CameraSystem>();backend.SetGuiScene(nullptr);texture.Destroy();backend.Shutdown();
}
int main(int argc,char**){Simulation();AdvancedModules();Imports();if(argc>1)GPU();}
